def run(_context: str):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for o in root.occurrences:
        bb = o.boundingBox
        print(o.name, [round(v*10,2) for v in (bb.minPoint.x,bb.minPoint.y,bb.minPoint.z,bb.maxPoint.x,bb.maxPoint.y,bb.maxPoint.z)])
        for b in o.component.bRepBodies:
            print('  body', b.name, round(b.volume*1000,1), 'mm3')
    tl = design.timeline
    for i in range(tl.count):
        it = tl.item(i)
        print(i, it.name, it.healthState, it.errorOrWarningMessage)
    for p in design.userParameters:
        print(p.name, p.expression)

import adsk.core, adsk.fusion

def run(_context: str):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    print('root bodies', root.bRepBodies.count)
    def r(bb):
        return [round(v*10,1) for v in (bb.minPoint.x,bb.minPoint.y,bb.minPoint.z,bb.maxPoint.x,bb.maxPoint.y,bb.maxPoint.z)]
    def walk(occs, depth):
        for o in occs:
            print('  '*depth + o.name, 'b', o.component.bRepBodies.count, r(o.boundingBox))
            if depth < 3:
                walk(o.childOccurrences, depth+1)
    walk(root.occurrences, 0)
    for b in root.bRepBodies:
        print('body', b.name, r(b.boundingBox))

import adsk.core, adsk.fusion

def r(bb):
    return [round(v*10,2) for v in (bb.minPoint.x,bb.minPoint.y,bb.minPoint.z,bb.maxPoint.x,bb.maxPoint.y,bb.maxPoint.z)]

def run(_context: str):
    app = adsk.core.Application.get()
    doc = [d for d in app.documents if d.name.startswith('lab2-cameras-reference')][0]
    design = adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType'))
    root = design.rootComponent
    x = [o for o in root.occurrences if o.name.startswith('XIAO')][0]
    def walk(o, d):
        print('  '*d + o.name, 'bodies', o.component.bRepBodies.count, r(o.boundingBox))
        for b in o.bRepBodies:
            print('  '*(d+1) + 'body', b.name, r(b.boundingBox))
        for c in o.childOccurrences:
            walk(c, d+1)
    walk(x, 0)

import adsk.core, adsk.fusion

def run(_context: str):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    comp = [c for c in design.allComponents if c.name == 'XIAO_square_mount'][0]
    sk = comp.sketches.itemByName('cover_screw_holes')
    feat = None
    for e in comp.features.extrudeFeatures:
        if e.operation == adsk.fusion.FeatureOperations.CutFeatureOperation and e.profile and e.profile.parentSketch == sk if hasattr(e.profile, 'parentSketch') else False:
            feat = e
    if feat is None:
        for e in comp.features.extrudeFeatures:
            if e.operation == adsk.fusion.FeatureOperations.CutFeatureOperation:
                feat = e
    print('feature', feat.name)
    ta = adsk.fusion.ThroughAllExtentDefinition.create()
    tb = adsk.fusion.ThroughAllExtentDefinition.create()
    feat.setTwoSidesExtent(ta, tb)
    b = comp.bRepBodies.itemByName('mount')
    for f in b.faces:
        g = f.geometry
        if isinstance(g, adsk.core.Cylinder) and abs(g.radius*20 - 2.9) < 0.01:
            bb = f.boundingBox
            print('hole D2.9 at x', round((bb.minPoint.x+bb.maxPoint.x)*5,1), 'y', round(bb.minPoint.y*10,1), '..', round(bb.maxPoint.y*10,1), 'z', round((bb.minPoint.z+bb.maxPoint.z)*5,1))

