            print('  ', cv.objectType.split('::')[-1], 'fully', cv.isFullyConstrained, 'ref', cv.isReference)
        for p in sk.sketchPoints:
            print('   pt', round(p.geometry.x*10,2), round(p.geometry.y*10,2), 'fixed?', p.isFixed, 'fully', p.isFullyConstrained if hasattr(p,'isFullyConstrained') else '')

import adsk.core, adsk.fusion

def bb(b):
    x = b.boundingBox
    return f'({x.minPoint.x*10:.1f},{x.minPoint.y*10:.1f},{x.minPoint.z*10:.1f})..({x.maxPoint.x*10:.1f},{x.maxPoint.y*10:.1f},{x.maxPoint.z*10:.1f})'

def run(_context: str):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    print('doc', app.activeDocument.name)
    root = design.rootComponent
    for o in root.allOccurrences:
        n = o.component.name
        if n in ('Camer Module', 'PCB', 'Sense Expansion Board', 'XIAO_square_mount', 'JUSHUO AFC01-S24FCA-00', 'Seeed Studio XIAO-ESP32-S3 (Sense)', 'USB TYPE C PORT', 'SKTAAAE010 v1', 'DF40HC(3.0)-30DS'):
            for b in o.bRepBodies:
                if b.volume > 0.001:
                    print(f'{o.fullPathName[-70:]} | {b.name} | vol {b.volume*1000:.0f} mm3 | {bb(b)}')
